def field(name: str, type_: str, required: bool, description: str, example: Any=None, constraints: str='', location: str='body') -> dict[str, Any]:
    result = {'name': name, 'type': type_, 'required': required, 'description': description, 'constraints': constraints, 'location': location}
    if example is not None:
        result['example'] = example
    return result
