def _timeout_values(configuration: dict[str, Any] | None, config_error: bool) -> list[dict[str, Any]]:
    settings = (configuration or {}).get('settings', {})
    values = []
    for record in TIMEOUTS:
        item = copy.deepcopy(record)
        saved = settings.get(item['id'])
        valid = isinstance(saved, (int, float)) and (not isinstance(saved, bool)) and (saved > 0)
        item['value'] = saved if valid else item['default']
        item['source'] = 'saved_config' if valid else 'source_default'
        item['confirmed'] = valid and (not config_error)
        values.append(item)
    return values

def build_reference(models: dict[str, Any] | None=None, configuration: dict[str, Any] | None=None, *, registry_error: bool=False, config_error: bool=False, base_url: str=DEFAULT_BASE_URL) -> dict[str, Any]:
    timeouts = _timeout_values(configuration, config_error)
    timeout_map = {item['id']: item for item in timeouts}
    live_models = (models or {}).get('data', []) if isinstance(models, dict) else []
    endpoints = copy.deepcopy(ENDPOINTS)
    for endpoint in endpoints:
        capabilities = set(endpoint.pop('capabilities', []))
        fixed_models = set(endpoint.pop('model_ids', []))
        example_model = endpoint.pop('example_model', None)
        example_profile = endpoint.pop('example_profile', None)
        endpoint['auth'] = endpoint.get('auth', True)
        if endpoint['auth']:
            endpoint['error_codes'] = list(dict.fromkeys(['invalid_api_key', 'api_key_expired', 'rate_limit_exceeded', *endpoint['error_codes']]))
        endpoint['models'] = [item['id'] for item in live_models if item.get('capability') in capabilities and (not fixed_models or item.get('id') in fixed_models)]
        endpoint['models_confirmed'] = not registry_error
        endpoint['examples'] = examples_for(example_model, example_profile, base_url) if example_model and example_profile else []
        timeout_id = endpoint.get('timeout')
        endpoint['timeout_value'] = timeout_map.get(timeout_id)
        endpoint['errors'] = [{'status': status, 'code': code, 'meaning': meaning, 'action': action} for status, code, meaning, action in ERRORS if code in endpoint['error_codes']]
    return {'schema_version': 1, 'generated_at': datetime.now(timezone.utc).isoformat(timespec='seconds'), 'base_url': base_url, 'registry_available': not registry_error, 'config_available': not config_error, 'authentication': {'type': 'http_bearer', 'header': 'Authorization: Bearer <API_KEY>', 'description': '所有 /v1 HTTP 接口和 ASR WebSocket 都需要业务 API Key；/health 与 /health/live 不需要。'}, 'request_id': '客户端可传 X-Request-ID（最多 128 字符）；响应始终返回 X-Request-ID。', 'error_shape': {'example': {'error': {'message': 'Model is not active', 'type': 'service_unavailable_error', 'param': 'model', 'code': 'model_inactive'}, 'request_id': 'request-id'}, 'rules': ['先按 HTTP 状态分类，再按 error.code 处理。', '429 使用 Retry-After；其余错误不能默认自动重试。', '流式 HTTP 200 后仍需处理 SSE error 事件。']}, 'protocols': copy.deepcopy(PROTOCOLS), 'timeouts': timeouts, 'errors': [{'status': status, 'code': code, 'meaning': meaning, 'action': action} for status, code, meaning, action in ERRORS], 'endpoints': endpoints, 'notice': '此页描述公共网关合同。模型是否在线、输入质量边界和验收状态仍以模型能力页及自检记录为准。'}
