OPENAPI_REQUEST_SCHEMAS = {'chat': 'ChatCompletionRequest', 'embeddings': 'EmbeddingRequest', 'rerank': 'RerankRequest', 'tts': 'SpeechRequest', 'asr': 'TranscriptionRequest', 'legacy-ocr': 'LegacyOcrRequest'}
OPENAPI_RESPONSE_SCHEMAS = {'models': 'ModelList', 'chat': 'ChatCompletionResponse', 'embeddings': 'EmbeddingResponse', 'rerank': 'RerankResponse', 'cv': 'CvResponse', 'asr': 'TranscriptionResponse', 'legacy-ocr': 'ChatCompletionResponse', 'health-live': 'LiveHealth', 'health': 'Health'}

def _schema_for_field(record: dict[str, Any]) -> dict[str, Any]:
    type_name = record['type']
    if 'binary' in type_name.lower():
        return {'type': 'string', 'format': 'binary', 'description': record['description']}
    if type_name in {'integer', 'number', 'boolean', 'string'}:
        schema = {'type': type_name, 'description': record['description']}
        if 'example' in record:
            schema['example'] = record['example']
        return schema
    if type_name.endswith('[]') or type_name.startswith('array'):
        return {'type': 'array', 'items': {}, 'description': record['description']}
    return {'description': record['description']}

def _request_schema(endpoint: dict[str, Any]) -> dict[str, Any]:
    body_fields = [item for item in endpoint['request_fields'] if item['location'] == 'body']
    properties = {item['name']: _schema_for_field(item) for item in body_fields}
    required = [item['name'] for item in body_fields if item['required']]
    result: dict[str, Any] = {'type': 'object', 'properties': properties, 'additionalProperties': True}
    if required:
        result['required'] = required
    return result

def build_openapi(reference: dict[str, Any]) -> dict[str, Any]:
    error_schema = {'type': 'object', 'required': ['error', 'request_id'], 'properties': {'error': {'type': 'object', 'required': ['message', 'type', 'code'], 'properties': {'message': {'type': 'string'}, 'type': {'type': 'string'}, 'param': {'type': ['string', 'null']}, 'code': {'type': 'string'}, 'details': {}}}, 'request_id': {'type': 'string'}}}
    schemas = copy.deepcopy(OPENAPI_SCHEMAS)
    schemas['GatewayError'] = error_schema
    error_lookup = {item['code']: item for item in reference['errors']}
    paths: dict[str, Any] = {}
    websocket = []
    for endpoint in reference['endpoints']:
        if endpoint['method'] == 'WS':
            websocket.append({key: endpoint[key] for key in ('path', 'title', 'summary', 'request_fields', 'response_fields', 'streaming')})
            continue
        for path in [endpoint['path'], *endpoint['aliases']]:
            parameters = []
            for item in endpoint['request_fields']:
                if item['location'] not in {'path', 'query', 'header'}:
                    continue
                parameters.append({'name': item['name'], 'in': item['location'], 'required': item['required'], 'description': item['description'], 'schema': _schema_for_field(item)})
            operation: dict[str, Any] = {'operationId': endpoint['id'] + ('Alias' if path != endpoint['path'] else ''), 'tags': [endpoint['group']], 'summary': endpoint['title'], 'description': endpoint['summary'], 'parameters': parameters, 'responses': {}, 'security': [{'BearerAuth': []}] if endpoint['auth'] else [], 'x-error-codes': endpoint['error_codes'], 'x-models': endpoint['models']}
            response_content: dict[str, Any] = {}
            for media in endpoint['response_content_type'].split(' / '):
                media = media.strip()
                if media == 'audio/wav':
                    schema = {'type': 'string', 'format': 'binary'}
                elif media in {'text/plain', 'text/event-stream'}:
                    schema = {'type': 'string'}
                else:
                    schema_name = OPENAPI_RESPONSE_SCHEMAS.get(endpoint['id'])
                    schema = {'$ref': f'#/components/schemas/{schema_name}'} if schema_name else {'type': 'object', 'additionalProperties': True}
                response_content[media] = {'schema': schema}
            operation['responses']['200'] = {'description': '成功', 'content': response_content}
            by_status: dict[int, list[str]] = {}
            for code in endpoint['error_codes']:
                if code in error_lookup:
                    by_status.setdefault(error_lookup[code]['status'], []).append(code)
            for status, codes in by_status.items():
                operation['responses'][str(status)] = {'description': '可能的 error.code：' + '、'.join(codes), 'content': {'application/json': {'schema': {'$ref': '#/components/schemas/GatewayError'}}}}
            operation['responses']['default'] = {'description': '其他网关错误', 'content': {'application/json': {'schema': {'$ref': '#/components/schemas/GatewayError'}}}}
            if endpoint['timeout_value']:
                operation['x-timeout-seconds'] = endpoint['timeout_value']['value']
            if path != endpoint['path']:
                operation['x-alias-of'] = endpoint['path']
            if endpoint['streaming']:
                operation['x-streaming'] = endpoint['streaming']
            if endpoint['content_type']:
                media = endpoint['content_type'].split(' | ')[0]
                schema_name = OPENAPI_REQUEST_SCHEMAS.get(endpoint['id'])
                request_schema = {'$ref': f'#/components/schemas/{schema_name}'} if schema_name else _request_schema(endpoint)
                request_content = {media: {'schema': request_schema}}
                if endpoint['id'] == 'cv':
                    binary = {'schema': {'type': 'string', 'format': 'binary'}}
                    request_content = {kind: binary for kind in ('image/png', 'image/jpeg', 'image/webp', 'application/octet-stream')}
                operation['requestBody'] = {'required': any((item['required'] and item['location'] == 'body' for item in endpoint['request_fields'])), 'content': request_content}
            paths.setdefault(path, {})[endpoint['method'].lower()] = operation
    return {'openapi': '3.1.0', 'info': {'title': 'AI Model Gateway Public API', 'version': '0.9.0', 'description': 'ModelDeck 维护的公共业务接口合同；管理接口不包含在此文件中。'}, 'servers': [{'url': reference['base_url'], 'description': '默认盒子地址'}], 'tags': [{'name': name} for name in dict.fromkeys((item['group'] for item in reference['endpoints']))], 'paths': paths, 'components': {'securitySchemes': {'BearerAuth': {'type': 'http', 'scheme': 'bearer', 'description': 'ModelDeck 创建的业务 API Key'}}, 'schemas': schemas}, 'x-websocket-endpoints': websocket, 'x-generated-at': reference['generated_at']}
